for (const [src, b] of Object.entries(BLOCS)) {
  const n = {};
  for (const [niveau, domaine, sousDomaine, texte] of b.lignes) {
    const key = `${niveau}-${domaine.split(",")[0]}`.toLowerCase().normalize("NFD").replace(/[^a-z0-9-]/g, "");
    n[key] = (n[key] || 0) + 1;
    COMPETENCES.push({ id: `${src}-${key}-${n[key]}`, cycle: b.cycle, niveau, discipline: b.discipline, domaine, sousDomaine, texte, source: src });
  }
}

